// ── 取得 period 參數，預設 7d ──
const period = $input.first().json.query?.period || '7d';

// ── 計算起始日期 ──
const now = new Date();
let days;
if (period === '90d') days = 90;
else if (period === '30d') days = 30;
else days = 7;

const startDate = new Date(now);
startDate.setDate(startDate.getDate() - (days - 1));
startDate.setHours(0, 0, 0, 0);

// 【優化】使用在地化日期格式，避免 UTC 時區導致日期少一天
const startDateStr = startDate.toLocaleDateString('en-CA'); 

// 傳給下一個節點
return [{
  json: {
    period,
    days,
    startDateISO: startDate.toISOString(),
    startDateStr: startDateStr // 確保這裡輸出的格式是 YYYY-MM-DD
  }
}];

const params = $('解析參數').first().json;
const items  = $input.all();
const { days, period } = params;
const now = new Date();

// ── 輔助
function getStatus(item) {
  return item.json.properties?.['案件狀態']?.select?.name || '';
}
function getType(item) {
  return item.json.properties?.['案件類型']?.select?.name || '未分類';
}
function getCloseDate(item) {
  return item.json.properties?.['結案日期']?.date?.start || null;
}

// ── 建立日期陣列（起始日到今天）
const dateMap = {};
for (let i = days - 1; i >= 0; i--) {
  const d = new Date(now);
  d.setDate(d.getDate() - i);
  const key = d.toISOString().split('T')[0];
  let label = '';
  if (days <= 7)       label = `${d.getMonth()+1}/${d.getDate()}`;
  else if (days <= 30) label = (i % 7 === 0 || i === 0) ? `${d.getMonth()+1}/${d.getDate()}` : '';
  else                 label = (i % 10 === 0 || i === 0) ? `${d.getMonth()+1}/${d.getDate()}` : '';
  dateMap[key] = { label, newCount: 0, closedCount: 0 };
}

// ── 每日新增件數（Simplify OFF 後路徑正確）
for (const item of items) {
  const created = item.json.created_time || item.json.properties?.['建立時間']?.date?.start || '';
  const key = created.split('T')[0];
  if (dateMap[key]) dateMap[key].newCount += 1;
}

// ── 每日結案件數（結案日期）
for (const item of items) {
  if (getStatus(item) !== '已結案') continue;
  const closeDate = getCloseDate(item);
  if (!closeDate) continue;
  const key = closeDate.split('T')[0];
  if (dateMap[key]) dateMap[key].closedCount += 1;
}

const chart = Object.values(dateMap);

// ── 當月統計
const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
let msNew = 0, msClosed = 0, msProgress = 0;
for (const item of items) {
  const created = item.json.created_time;
  if (created && new Date(created) >= monthStart) msNew++;
  const status = getStatus(item);
  if (status === '已結案') {
    const cd = getCloseDate(item);
    if (cd && new Date(cd) >= monthStart) msClosed++;
  } else if (status === '處理中') {
    msProgress++;
  }
}

// ── 類別比例（依所選期間）
const typeCounts = {};
for (const item of items) {
  const type = getType(item);
  typeCounts[type] = (typeCounts[type] || 0) + 1;
}

return [{
  json: {
    success: true,
    period,
    chart,
    monthStats: {
      newCount:      msNew,
      closedCount:   msClosed,
      progressCount: msProgress
    },
    typeCounts
  }
}];
